config.script:
# Dev only (epic 2 story 11): seed the mapstudio-dev map with the 30-pad scale set and the
# tracer's points through system.mapstudio (project library mapstudio_seed), then the
# mapstudio-showcase map with the UX mockups' demo field and its demo tags' states (project
# library mapstudio_showcase_seed, epic 3 entry 15; its result under 'showcase'). Safe to re-run.
import java.lang

logger = system.util.getLogger('MapStudio.seed')
out = self.view.rootContainer.getChild('seedResult')

# The scripting API trusts its caller (docs/contract.md), so this view checks the role itself,
# as the script checks do: only a signed-in session whose user holds MapEditor may seed.
if not mapstudio_dev.holdsMapEditor(self.session):
	out.props.text = system.util.jsonEncode({'refused': 'Seeding writes to the map store, so it needs the MapEditor role. Sign in as a map editor first.', 'ranAt': system.date.toMillis(system.date.now())})
	logger.info('Dev seed refused: the session user does not hold MapEditor.')
	return

try:
	result = mapstudio_seed.run()
except java.lang.Throwable as ex:
	result = {'error': ex.getMessage()}
	logger.warn('Dev seed failed: %s' % ex.getMessage())
except Exception as ex:
	result = {'error': str(ex)}
	logger.warn('Dev seed failed: %s' % ex)
if 'error' not in result:
	try:
		result['showcase'] = mapstudio_showcase_seed.run()
	except java.lang.Throwable as ex:
		result['showcase'] = {'error': ex.getMessage()}
		logger.warn('Showcase seed failed: %s' % ex.getMessage())
	except Exception as ex:
		result['showcase'] = {'error': str(ex)}
		logger.warn('Showcase seed failed: %s' % ex)
# ranAt tells two runs with the same result apart.
result['ranAt'] = system.date.toMillis(system.date.now())
out.props.text = system.util.jsonEncode(result)
